import re
text = HTML.read_text(encoding='utf-8')
text = re.sub(r'\s*<script id="sleeprise-v53-language-onboarding">.*?</script>\s*', '\n', text, count=1, flags=re.S)
layer = LAYER.replace('\\n', '\n')
text = text.rstrip() + '\n' + layer + '\n'
HTML.write_text(text, encoding='utf-8')
print('v53 layer normalized to file end')
